-- Decks are drawn on slide masters read from .pptx files (lib/pptx/import.ts)
-- instead of a template id: each deck carries its master and its layouts.
-- Master files (a .pptx without its slides) are kept by sha256 for export;
-- the built-in ones ship in template/ and are not stored here.
create table masters (
  sha256 text primary key,
  bytes bytea not null,
  master jsonb not null,                     -- the master as read, for set_master
  created_at timestamptz not null default now()
);

-- Who may put a deck on a master file: everyone who imported it.
create table master_owners (
  sha256 text not null references masters (sha256) on delete cascade,
  sub text not null references users (sub) on delete cascade on update cascade,
  created_at timestamptz not null default now(),
  primary key (sha256, sub)
);

-- Existing decks take the built-in master their template named, as
-- lib/master/builtin.json held it when this ran.
